-- Read-only original earnings dashboard, not order gross or cash collected.
create function core_auth.courier_earnings_fixture(p_period text) returns jsonb
language plpgsql security definer set search_path='' as $fn$
begin
 perform core_auth.courier_shift_fixture('ready');
 if p_period is null or p_period not in ('hoje','semana','mes') then raise exception 'Período inválido' using errcode='22023';end if;
 -- Original function chooses an active courier by user. Fail closed on ambiguous
 -- identities rather than returning earnings from a different membership.
 if (select count(*) from public.couriers c where c.user_id=auth.uid() and c.active and c.store_id is not null)<>1 then
  raise exception 'Identidade ambígua' using errcode='42501';
 end if;
 if not exists(select 1 from public.couriers c join core_auth.memberships m on m.store_id=c.store_id and m.user_id=c.user_id and m.active and m.role='courier' join core_auth.stores st on st.id=m.store_id and st.active where c.user_id=auth.uid() and c.active and c.fleet_type='propria') then
  raise exception 'Escopo não autorizado' using errcode='42501';
 end if;
 return public.pitacco_driver_earnings(p_period);
end $fn$;
revoke all on function core_auth.courier_earnings_fixture(text) from public,anon,authenticated;
grant execute on function core_auth.courier_earnings_fixture(text) to pitacco_core_courier_payment;

-- CI-only safe history. Preserve original masked history fields, including
-- the current app's cancelled bucket. No direct delivery/receipt access.
create function core_auth.courier_history_fixture(p_limit integer) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare result jsonb;
begin
 perform core_auth.courier_shift_fixture('ready');
 if p_limit is null or p_limit not between 1 and 50 then raise exception 'Limite inválido' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object(
  'number',coalesce(public.pitacco_order_public_label(o.receipt,coalesce(o.source,d.source)),'Número indisponível'),
  'source',d.source,'status',d.status,'completed_at',d.updated_at,'finished_at',d.updated_at,
  'arrived_at',d.arrived_at,'amount',case when d.status='cancelada' then 0 else d.courier_payment end,
  'initial',case when nullif(btrim(d.customer_name),'') is null then 'C.' else upper(left(btrim(d.customer_name),1))||'.' end,
  'address_hint',case when nullif(btrim(d.address),'') is null then 'Endereço resumido indisponível' else left(btrim(split_part(d.address,',',1)),8)||'…' end
 ) order by d.updated_at desc,d.id),'[]'::jsonb) into result
 from (
  select x.* from public.deliveries x
  join public.couriers c on c.id=x.courier_id and c.store_id=x.store_id and c.user_id=auth.uid() and c.active and c.fleet_type='propria'
  join core_auth.memberships m on m.user_id=c.user_id and m.store_id=c.store_id and m.active and m.role='courier'
  join core_auth.stores st on st.id=m.store_id and st.active
  where x.status in ('entregue','cancelada') and x.logistics_provider='loja' and x.source in ('proprio','ifood')
  order by x.updated_at desc,x.id limit p_limit
 ) d left join public.orders o on o.id=d.order_id and o.store_id=d.store_id;
 return result;
end $fn$;
revoke all on function core_auth.courier_history_fixture(integer) from public,anon,authenticated;
grant execute on function core_auth.courier_history_fixture(integer) to pitacco_core_courier_payment;

-- CI-only detail: same original shape, explicit active assignment and private
-- marketplace contact. No raw receipt, credit balance, delivery code or token.
create function core_auth.courier_detail_fixture(p_delivery uuid) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare d public.deliveries%rowtype; o public.orders%rowtype; v jsonb; contact jsonb; ct public.pitacco_delivery_customer_contacts%rowtype; phone text; locator text; expires timestamptz; kind text; payment jsonb; items jsonb;
begin
 perform core_auth.courier_shift_fixture('ready');
 select x.* into d from public.deliveries x
 join public.couriers c on c.id=x.courier_id and c.store_id=x.store_id and c.user_id=auth.uid() and c.active and c.fleet_type='propria'
 join core_auth.memberships m on m.store_id=x.store_id and m.user_id=c.user_id and m.active and m.role='courier'
 join core_auth.stores s on s.id=m.store_id and s.active
 where x.id=p_delivery and x.status in ('atribuida','aceita','retirada') and x.logistics_provider='loja' and x.source in ('proprio','ifood');
 if not found then raise exception 'Entrega não autorizada' using errcode='42501';end if;
 select * into o from public.orders where id=d.order_id and store_id=d.store_id and source=d.source and status='accepted';
 if not found or (d.source='ifood' and (coalesce(o.receipt->>'ifood_status','') not in ('CONFIRMED','READY_TO_PICKUP','DISPATCHED') or coalesce(o.receipt->>'ifood_manual_cancel','')='requested')) then raise exception 'Pedido indisponível' using errcode='42501';end if;
 v:=coalesce(o.receipt,'{}'::jsonb);
 select * into ct from public.pitacco_delivery_customer_contacts where delivery_id=d.id and store_id=d.store_id;
 expires:=ct.phone_expires_at;
 phone:=nullif(trim(ct.phone_number),'');locator:=nullif(trim(ct.phone_localizer),'');
 if d.source='proprio' and phone is null then
  select nullif(trim(pc.phone),'') into phone from public.public_checkouts pc where pc.order_id=o.id and pc.store_id=o.store_id order by pc.created_at desc limit 1;
 end if;
 kind:=case when phone is null then 'none' when regexp_replace(phone,'[^0-9]','','g')~'^0(800|300|303|900)[0-9]+$' then 'intermediary' when regexp_replace(phone,'[^0-9]','','g')~'^(55)?[1-9][0-9](9[0-9]{8}|[2-9][0-9]{7})$' then 'real' else 'unknown' end;
 if expires is not null and expires<=now() then phone:=null;locator:=null;kind:='expired';end if;
 contact:=jsonb_build_object('number',phone,'kind',kind,'localizer',locator,'expires_at',expires);
 payment:=pitacco_private.courier_payment_details(v,o.gross);
 if lower(coalesce(v->>'payment_method',v->'payment'->>'method',v->>'payment',''))='fiado' then payment:=jsonb_build_object('method','Sem cobrança na entrega','state','no_collect');end if;
 select coalesce(jsonb_agg(jsonb_build_object('name',coalesce(i->>'name',i->>'title','Produto'),'quantity',coalesce(i->>'quantity','1'),'notes',coalesce(i->>'notes',i->>'observations',''),'options',
 (select coalesce(jsonb_agg(jsonb_build_object('name',case when jsonb_typeof(m)='string' then m#>>'{}' else coalesce(m->>'name',m->>'title',m->'option'->>'name','') end,'quantity',coalesce(m->>'quantity','1')) order by k),'[]'::jsonb) from jsonb_array_elements(case when jsonb_typeof(i->'modifiers')='array' then i->'modifiers' when jsonb_typeof(i->'options')='array' then i->'options' when jsonb_typeof(i->'complements')='array' then i->'complements' else '[]'::jsonb end) with ordinality as mm(m,k))) order by n),'[]'::jsonb) into items
 from jsonb_array_elements(case when jsonb_typeof(v->'items')='array' then v->'items' else '[]'::jsonb end) with ordinality as ii(i,n) where jsonb_typeof(i)='object';
 return jsonb_build_object('delivery_id',d.id,'order_id',o.id,'display_number',coalesce(public.pitacco_order_public_label(v,o.source),'Aguardando número'),'status',d.status,'source',d.source,'customer_name',d.customer_name,'address',d.address,'notes',coalesce(nullif(d.notes,''),v->>'notes',''),'items',items,'total',o.gross,'payment_method',payment->>'method','payment_status',case when payment->>'state'='no_collect' then 'no_collect' else v->>'payment_status' end,'contact',contact);
end $fn$;
revoke all on function core_auth.courier_detail_fixture(uuid) from public,anon,authenticated;
grant execute on function core_auth.courier_detail_fixture(uuid) to pitacco_core_courier_payment;

-- CI-only read model for the unchanged courier map. Explicit same-store scope;
-- exact coordinates are visible only to the assigned authenticated courier.
create function core_auth.courier_map_fixture() returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare origins jsonb; stops jsonb; gps jsonb;
begin
 perform core_auth.courier_shift_fixture('ready');
 select coalesce(jsonb_agg(q order by q.store_id),'[]'::jsonb) into origins from (
  select distinct s.id as store_id,s.latitude,s.longitude
  from public.stores s join public.couriers c on c.store_id=s.id and c.active and c.fleet_type='propria' and c.user_id=auth.uid()
  join core_auth.memberships m on m.store_id=s.id and m.user_id=c.user_id and m.active and m.role='courier'
  join core_auth.stores st on st.id=m.store_id and st.active
 ) q;
 select coalesce(jsonb_agg(q order by q.created_at desc,q.id),'[]'::jsonb) into stops from (
  select d.id,d.store_id,d.order_id,d.batch_id,d.status,d.source,d.logistics_provider,d.latitude,d.longitude,d.address,d.created_at,d.collected_at,d.arrived_at,d.deliver_by,
   case when o.receipt->>'delivery_service'='priority' then 'priority' else 'standard' end as delivery_service,
   public.pitacco_order_public_label(o.receipt,o.source) as public_number
  from public.deliveries d join public.couriers c on c.id=d.courier_id and c.store_id=d.store_id and c.user_id=auth.uid() and c.active and c.fleet_type='propria'
  join core_auth.memberships m on m.store_id=d.store_id and m.user_id=c.user_id and m.active and m.role='courier'
  join core_auth.stores st on st.id=m.store_id and st.active
  join public.orders o on o.id=d.order_id and o.store_id=d.store_id and o.source=d.source and o.status='accepted'
  where d.status in ('atribuida','aceita','retirada') and d.logistics_provider='loja' and d.source in ('proprio','ifood')
   and (d.source='proprio' or (o.receipt->>'ifood_status' in ('CONFIRMED','READY_TO_PICKUP','DISPATCHED') and coalesce(o.receipt->>'ifood_manual_cancel','')<>'requested'))
 ) q;
 select to_jsonb(q) into gps from (
  select p.latitude,p.longitude,p.accuracy_m,p.observed_at
  from public.courier_positions p join public.couriers c on c.id=p.courier_id and c.user_id=auth.uid() and c.active and c.available and c.fleet_type='propria'
  join core_auth.memberships m on m.store_id=c.store_id and m.user_id=c.user_id and m.active and m.role='courier'
  join core_auth.stores st on st.id=m.store_id and st.active
  where p.observed_at between now()-interval '120 seconds' and now()+interval '30 seconds'
    and p.accuracy_m between 0 and 2000
    and p.latitude between -90 and 90 and p.longitude between -180 and 180
    and (p.latitude<>0 or p.longitude<>0)
  order by p.observed_at desc limit 1
 ) q;
 return jsonb_build_object('origins',origins,'deliveries',stops,'gps',gps);
end $fn$;
revoke all on function core_auth.courier_map_fixture() from public,anon,authenticated;
grant execute on function core_auth.courier_map_fixture() to pitacco_core_courier_payment;
